#!/usr/bin/python3
from __future__ import print_function

import os
import sqlite3
import sys


base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
db_path = os.path.join(base, 'catalog.db')
db = sqlite3.connect(db_path)

try:
    db.execute('PRAGMA foreign_keys = ON')
    db.execute('BEGIN IMMEDIATE')

    versions = db.execute(
        'SELECT version FROM schema_version'
    ).fetchall()
    columns = {
        row[1]: row for row in db.execute('PRAGMA table_info(products)')
    }

    if versions == [(2,)]:
        if 'price_cents' not in columns:
            raise RuntimeError(
                'schema claims version 2 but price_cents is missing'
            )
        db.commit()
        print('catalog schema is already at version 2')
    elif versions == [(1,)]:
        if 'price_cents' in columns:
            raise RuntimeError(
                'schema is version 1 but price_cents already exists'
            )

        db.execute(
            'ALTER TABLE products ADD COLUMN price_cents '
            'INTEGER NOT NULL DEFAULT 0 CHECK (price_cents >= 0)'
        )
        if db.execute(
            'SELECT COUNT(*) FROM products '
            'WHERE price_cents IS NULL OR price_cents < 0'
        ).fetchone()[0]:
            raise RuntimeError('invalid price_cents values')

        cursor = db.execute(
            'UPDATE schema_version SET version = 2 WHERE version = 1'
        )
        if cursor.rowcount != 1:
            raise RuntimeError('failed to advance schema version')

        db.commit()
        print('catalog schema upgraded from version 1 to 2')
    else:
        raise RuntimeError(
            'expected exactly one schema version row at version 1 or 2'
        )
except Exception as error:
    db.rollback()
    print('upgrade failed: {0}'.format(error), file=sys.stderr)
    sys.exit(1)
finally:
    db.close()
